sys_script_client.script:
function onLoad() {

    var category = g_form.getValue('category');

    if (category != 'sla') {
        g_form.setDisplay('duration', false);
        g_form.setDisplay('unique_id', false);
    }

    if (g_user.hasRoleExactly('x_hsb11_mss_trus_0.ops_admin') ||
        g_user.hasRoleExactly('x_hsb11_mss_trus_0.complaint_admin')) {
        g_form.setDisplay('unique_id', false);
        if (g_form.isNewRecord()) {
            g_form.removeOption('category', 'sla', 'SLA');
        } else if (category == 'sla') {
            g_form.setReadOnly('name', true);
            g_form.setReadOnly('category', true);
            g_form.setReadOnly('active', true);
            g_form.setReadOnly('element', true);
            g_form.setMandatory('duration', true);
        } else if (category == 'choice') {
            g_form.setReadOnly('category', true);
            g_form.setReadOnly('element', true);
        }
    }

}
